import type { Localized } from '@/lib/i18n'

/**
 * English translations for "חרדית מדוברת" (Haredit Meduberet) episode
 * titles and descriptions, keyed by the same id `toEpisode()`/
 * `toLiveEpisode()` (src/content/podcast.ts) already use: a YouTube
 * `videoId` for live/archive episodes, the fixture's own numeric `id` for
 * the last-resort `RAW_EPISODES` fallback.
 *
 * 2026-08-31 brief: "אני רוצה לתרגם את התוכן של חרדית מדוברת, כי גם אם
 * הקורא לא יקשיב, הוא יראה אלו סוגיות אני מכסה, זה חשוב בעיקר לתורמים".
 * Until now every episode's `en` locale silently duplicated the Hebrew text
 * (see `toLiveEpisode()`'s own doc comment), so an English-reading visitor
 * saw the exact same Hebrew title/description an `he` reader did. This
 * table covers every episode in `podcast-archive.json` as of this sync
 * (104 episodes) plus the 6-item `RAW_EPISODES` last-resort fallback.
 *
 * Deliberately its own file, not baked into `podcast-archive.json` itself:
 * `npm run sync-podcast-archive` REWRITES that file wholesale from a fresh
 * YouTube walk (scripts/sync-podcast-archive.mjs), which would silently
 * discard any `en` field added there. A separate, hand-maintained table
 * survives that resync intact.
 *
 * `description` here is the ENGLISH translation of the same first
 * paragraph `firstParagraph()` (src/content/podcast.ts) extracts from the
 * raw Hebrew description, the only part of the description any page ever
 * renders, not a translation of the full multi-paragraph text (which ends
 * in a repeated block of social-link boilerplate on every entry).
 *
 * A future episode not yet in this table simply has no entry here;
 * `toLiveEpisode()`/`toEpisode()` fall back to the Hebrew text for `en` in
 * that case, exactly like before this table existed. Never a broken page,
 * just an untranslated one until this table is next updated by hand.
 */
export const podcastTranslations: Record<string, { title: string; description: string }> = {
  "eakRf41F85U": { title: "A Conversation That Might Annoy Some Men :( | Esty Shushan Hosts Shelly Rapoport", description: "Yes, that risk is real, but we still thought these topics were worth talking about, because one day you might pass them on the street, in your neighborhood, or under a streetlamp, and think: how did I never notice?" },
  "QY04mPeFG84": { title: "Adventures of a Feminist in the Matchmaking Market | Esty Shushan Hosts Leah Sheinbrom", description: "What does the romantic dream of a Beit Yaakov girl look like, and what happens when it doesn't come true by twenty? Leah Sheinbrom, a clinical social worker, a graduate of Nivcharot and founder of the \"Sicha\" (Dialogue) group for exchanging views between feminist women and Haredi men, spent long years of singlehood in a world where every passing year is counted out loud, and married at an age considered late by Haredi standards." },
  "4U-DOPGUTNo": { title: "What Went Wrong in the Court of the Vizhnitz Dynasty? | Esty Shushan Hosts Yehuda Moses", description: "The Hasidic idea was born to give worth to the ordinary person and connect everyone to religious experience and to God. But in certain places it has curdled into total subjugation to a single flesh-and-blood figure, the Rebbe. Investigative reports by Aharon Rabinowitz and Yoeli Brim on the Vizhnitz-Merkaz Hasidic dynasty revealed just how far that can go: Hasidim required to trail behind the Rebbe everywhere as his human \"tails,\" kollel scholars selling their apartments and donating their savings funds to build a quarter-billion-shekel study hall, and an old feud that still fuels mass street brawls today." },
  "My8iGT3vvO0": { title: "Dad Is Watching From Above and Always Loves Me | Esty Shushan Hosts Ofir Tubul", description: "\"Dad Is Watching From Above\" was Shas's election slogan; \"God Always Loves Me\" became a wartime anthem. Against them stands the slogan \"We will die before we enlist,\" voiced by Shas's rabbis and leaders, pulling Mizrahi Israelis toward Haredi separatism." },
  "gZ8DT2KyM-s": { title: "In My Circle, No One Wants to Know What I Do | Esty Shushan Hosts Tzipi Horowitz", description: "Does Haredi society want to know what our security really costs? Who pays the price? And what happens to the bodies and minds of those who came back from it, never again to be who they were? In this episode of Haredit Meduberet, Esty Shushan hosts Tzipi Horowitz, a Haredi woman who works in the Defense Ministry's rehabilitation division and personally accompanies wounded soldiers, those hurt in body and in mind, on their path back to recovery. Tzipi speaks with raw honesty about how she got there, tracing it back to the days of early, unready motherhood that taught her to search for a path and to ask the questions she wasn't supposed to ask. She describes what it does to a Haredi woman to look, day after day, into the eyes of people who risked everything on the battlefield, to walk with them on the endless road back to life, and then to go home herself, to a community that would rather not know what her brothers and sisters paid for its peace of mind." },
  "Vu5wvlVEAv4": { title: "Game of Thrones in the Haredi Oligarchy | Esty Shushan Hosts Eli Bitan", description: "Haredi parties enter the 2026 election at the height of their political power, a dream coalition, every committee, every post, and a rock-solid political alliance with the religious bloc. And that's exactly where the paradox shows up: never have they been this strong, and never have they felt this defeated. Yeshiva students under arrest, sanctions, anger and fury boiling over in the Haredi street at a political leadership that doesn't really seem to know how to handle the moment." },
  "fH_Q82GkLeU": { title: "The Women's Section of Academia | Esty Shushan Hosts Malki Rothner", description: "Just before Haredit Meduberet heads to the polls, it wants to understand what this election is really about. A new series of episodes will try to unpack the issues fueling Israel's political discourse, with an outstanding lineup of guests." },
  "4VLCd5SZwrk": { title: "Believers at Odds | Esty Shushan Hosts Rabbi Sefi Gladzahler", description: "What separates Haredim from religious Zionists, and where do the messianic ideas that shape both of them come from? Is the Jewish people's role to be a light unto the nations, and if so, who's actually living that out? Has redemption already arrived, and what happens to Haredim who pour their entire lives into the \"Torah project\", do they gain from it, or do they lose whole dimensions of divine service, even of Torah itself? Why has Jerusalem Day, once an Israeli consensus, become a flashpoint of division? And why is it specifically Haredi symbols that newly religious Jews tend to adopt?" },
  "1gxmdTptMRo": { title: "A Bypass Route Around Beit Yaakov | Esty Shushan Hosts Yehudit Yifrach", description: "Yehudit Yifrach didn't study at Beit Yaakov. Then again, she isn't a ba'alat teshuvah (a newly religious returnee) either. She met Moshe, her husband, during the second round of Hakafot dancing at the Western Wall at age eighteen, and so, without preparing or planning for it, found herself inside Haredi society, a woman, a mother, in a world whose values she still finds herself questioning." },
  "Ry55sT63ESI": { title: "Torah Study and Conversion Therapy | Esty Shushan Hosts Rabbi Refael Yehonatan Polisuk", description: "In religious Zionism, this has become an open social battle. In Haredi society, it still isn't discussed. What happens to LGBTQ people born into Haredi or religious society?" },
  "nR20GETrMhY": { title: "Nice to Meet You, Nehorai | Esty Shushan Hosts Nehorai (Harry) Abergel", description: "Given all the baggage attached to the name Nehorai lately, and coming from a strongly Litvish yeshiva background, Nehorai (Harry) Abergel, journalist, social activist, a graduate of the Mir yeshiva, and a student of philosophy and international relations, has a request for Nehorais everywhere: stand up straight. In a satirical online bit announcing the founding of an \"International Association of Nehorais,\" he surfaces what he and others go through because of the traits people project onto that name. Along the way, he talks with Esty Shushan on Haredit Meduberet about the phenomenon of late singlehood in Haredi society, the social and political awareness he developed around his first and last names, how he ended up in civilian national service, what studying at Mir actually means, and how it shaped his path, plus at what point in his life he became \"Harry,\" and why the derided term \"Fricha,\" which literally just means \"flower,\" is actually a beautiful name." },
  "Hmfrhaqross": { title: "Love, Freedom, Marriage | Esty Shushan Hosts Rabbi Nir Menussi", description: "\"The sexual revolution has failed\", so argues Rabbi Nir Menussi in his book The Morning After, aimed primarily at secular readers. Is there another alternative that doesn't send us all back to the repressive days of the past? And from a critical Haredi perspective, what does that say about early marriage age, about boundaries of modesty that curdle into psychological distress? Can we even find a formula for a full, happy married life in our era?\nIn this episode of Haredit Meduberet, Esty Shushan hosts Rabbi Nir Menussi, rabbi, editor, author, and lecturer known for his work bridging Kabbalah and Hasidic thought with Western culture and modern psychology. A challenging conversation for Haredim and secular listeners alike. Buckle up!" },
  "0BmM-Iijxpg": { title: "When Community Suffocates | Esty Shushan Hosts Dr. Shimon Azulai", description: "Where's the line between a community that supports and helps, and one that squeezes a person until there's no air left of his own? All a person really needs in life is meaning, argues philosopher Dr. Shimon Azulai in his book The Meaning Revolution, and with that claim, he declares all-out war on Maslow and the hierarchy of needs he built, which placed meaning at the very bottom. In this episode he talks with Esty Shushan about the ideas in his book: the shift in consciousness that swept Israeli society after October 7th, which turned us from a comfortable, spoiled society chasing only happiness into a society in survival mode, drawing strength from solidarity and meaning; the global loneliness crisis; and the communal anchors of Haredi society, which are tested both against Western ideas of individualism and freedom, and against the way those very anchors narrow the range of choice available to someone growing up inside that world, and their odds of finding personal meaning on their own terms." },
  "NJxfPIH6tzQ": { title: "A Lesson in Haredi Masculinity | Esty Shushan Hosts Moishy Lifshitz", description: "While the Israeli ethos of masculinity is built on the army, Hollywood-style Western imagery, and toughness, the Haredi man grows up on the study hall, love of Torah, and fear of sin. How does that shape who he is?\nIn this episode of Haredit Meduberet, Moishy Lifshitz, raised in the Karlin Hasidic dynasty and Litvish yeshivas, now a writer for Makor Rishon and a literature student, shares insights with Esty Shushan on Haredi masculinity today.\nWhat's the difference between the Hasidic ideal of masculinity, which prizes gentleness and guarding one's eyes, and the Litvish ideal of competitive scholarship? Why does Hasidism specifically \"sacrifice feeling for the sake of the commandment\", and is it actually the Litvish man who allows himself simple human emotion?\nWhat happens to divorced fathers in Haredi society? Do they suffer more from parental alienation? How is the image of the divorced father shaped in his children's eyes?\nA lesson on masculinity, emotion, and gender like you've never heard it." },
  "tTXftw8fLc4": { title: "Don't Bring God Into This | Esty Shushan Hosts Aharon Rabinowitz", description: "With a string of investigations behind him that shook Haredi society, Aharon Rabinowitz, Haaretz's Haredi affairs correspondent, insists he sees his work as a religious calling, \"lighting a lamp on a dark street.\" In this episode of Haredit Meduberet, Aharon tells Esty Shushan what went on behind the scenes of the Chaim Walder and Yehuda Meshi-Zahav affairs, which he exposed together with his partner Shira Elk, including how he turned down a bribe of hundreds of thousands of shekels in exchange for his silence. He talks about the separatism that severs Torah from life, \"don't bring God into this,\" people tell him. He insists that you must. And about the stories still unpublished, because, he says, the public couldn't handle them." },
  "6LfLMGqZh8U": { title: "Did We Choose This Path? Esty Shushan Hosts Attorney and Rabbinical Court Pleader Vardit Rosenblum", description: "The great success of Haredi society's growth and consolidation allowed the generations born after its founding to walk a path already laid out for them. But did we lose the right to choose, a value rooted deep in Jewish thought? The ability to question, to search, and to find one's own way? Is there still a moment when a person stands alone before himself and his God and decides? One generation labors and chooses; the next inherits the achievement. Does a third generation understand the meaning of the inheritance in its hands?\nIn this episode of Haredit Meduberet, Esty Shushan opens up this question with Vardit Rosenblum: has Haredi society, which succeeded beyond anyone's expectations in preserving itself across three generations, lost something precious along the way, something more valuable than what it saved? The moment of choice itself.\nVardit, whose work includes Jewish thought and philosophy, talks about the pivotal choices in her own life that shaped her current path, from the new seminary in Jerusalem to her roles today as a rabbinical court pleader and attorney, a faculty member at the Mandel Institute, dean of the \"Public Emissaries\" program, and head of the Otot midrasha for Haredi women.\nA conversation that begins with Abraham the Hebrew smashing Terach's idols, and moves through the cost of inherited faith, women caught between obedience and autonomy, the tension between tradition and progress, and what we leave behind for the next generation." },
  "zqgNyP3Wl8U": { title: "Fraud, Mehadrin Style | Esty Shushan Hosts Simi Spolter", description: "How did Haredi society become a paradise for con artists and one of the deepest pools of fraud victims in Israel? It's a story of naivete and a lack of financial literacy, severe economic hardship, and the dream of getting rich quick. Young people with families and mortgages, with no tools to enter the job market, searching for a treasure chest. And when there's demand for financial miracles, someone will always show up to sell them and fleece unsuspecting kollel scholars, pyramid schemes with a kosher stamp of approval, fraud dressed up in all the right language, that knows exactly how badly people need to make it to the end of the month.\nIn this episode of Haredit Meduberet, Esty Shushan hosts Simi Spolter, a digital-media professional, a graduate of Litvish yeshivas, and a real estate, tech, and Haredi-economy reporter for TheMarker, for a conversation about the money that vanishes, the system that lets it happen, and what needs to change." },
  "_jfAxwAH--U": { title: "Not Puritanical, Not Permissive: Meet the Jewish Model for Healthy Sexuality", description: "Is there a third way between religious repression and Western permissiveness? Oria Mevorach presents \"the healthy Jewish discourse\", a revolutionary approach that isn't afraid of desire, but charges the body and the relationship with deep spiritual meaning." },
  "wJgtBgZvQnU": { title: "When Dad Stopped Believing | With Yochi Tefilinsky-Bloch", description: "Yochi Tefilinsky-Bloch was 11 when her world flipped upside down. Her father, a respected rabbi and halachic authority in the Haredi community, left home, left the community, and left religion. In his place came uncles, neighbors, family friends, who sat in her home as if sitting shiva for a father who was still alive. Yochi retreated into school, a safe, orderly place, and at night wrote him letters. The adults around her told her to stop missing him. She didn't stop.\nYears later, Yochi sits across from Esty Shushan and tells her story, and the story of her forced estrangement from her father, Avi Tefilinsky, creator of the series Behastora, broadcast on Kan 11, which raises awareness of the hidden world of Haredi anusim, people who have secretly abandoned their faith but continue living a double life inside the community, coping with concealment out of fear of losing their families, identities, and surroundings. Yochi talks about the recurring experience of loss, the stillbirth she went through, the long wait for her father, their reunion at age 17, and the woman she chose to become, Haredi, married, a social worker, a dance teacher.\nAn episode about a love that refuses to surrender to the rules of the game." },
  "lVtYoMo1cKo": { title: "Oria Mevorach Takes Us on a Fascinating Journey Through the Pages of the Talmud and Their Connection to Sexuality | From the Episode with Oria Mevorach", description: "How did the sages compare the Ark of the Covenant to a woman's body? Oria Mevorach takes us on a fascinating journey through the pages of the Talmud, revealing how the great Tannaim saw sexuality and modesty as tools for amplifying desire, not suppressing it. An eye-opening segment on some of the boldest sources in Judaism." },
  "z77t1ukcecg": { title: "The Empty Space in Halacha: Oria Mevorach on the Unbearable Pain of Late Singlehood", description: "What happens when the religious ideal collides with a broken heart? In a painful, exposed conversation, Esty Shushan and Oria Mevorach discuss the emotional cost of shmirat negiah (religious abstinence from physical touch) and singlehood in the religious world. Does Jewish law have any answers for this dead end?" },
  "HF60xfvabZo": { title: "Shattering the Illusion: Oria Mevorach on the Fight Against Silencing Sexual Abuse in the Religious Community", description: "\"Something big that I believed about the community I grew up in shattered.\" Oria Mevorach talks about her shift from writing and thinking to actively fighting sexual predators and the mechanisms that silence them in the community. Why is it so hard for us to believe survivors, and how can this reality be changed?" },
  "QFGORc75Fc0": { title: "Those Who Did Not Stand Idly By | Special Episode for Israel's Memorial Day 5786", description: "On this Memorial Day, Haredit Meduberet pauses to bow its head in memory of the fallen. Around the ever-troubling issue of Haredi enlistment, we've gathered the honest, painful, meaningful moments that came up on this podcast from those who spoke differently, who acted, and refused to sit on the sidelines even as the walls grew higher. From the episodes with Rabbi Refael Kroizer, Rabbi Elchanan Danino, Moshe Frigen, Yigal Guetta, and Rabbi Betzalel Cohen. Five voices that will keep echoing even as political interests continue to pollute public discourse and the push for integration, responsibility, and morality." },
  "aTlvl-GiP00": { title: "A Jarring Analysis: What the Derby Banner Reveals About How Pop Culture Humiliates Women | Oria Mevorach", description: "What happens when dirty assumptions seep onto the soccer field? Oria Mevorach and Esty Shushan analyze the now-infamous \"derby banner\" and explain the Madonna-whore complex that quietly runs our minds. How does porn culture and permissiveness affect the dignity of every woman?" },
  "9HOR-A0L71Q": { title: "The Lie of Sexual Freedom? Why Western Permissiveness Is Actually Puritanism in Disguise | Oria Mevorach", description: "Thought the Western world liberated the body? Think again. Oria Mevorach explains why \"permissive\" talk and \"dark religious\" talk are actually two sides of the same coin, both of them cheapening sexuality. A must-watch for anyone who wants to understand the psychology of sexuality in the modern era." },
  "D0WRgqXhTX8": { title: "From a Bridal Instructor's Desk | Esty Shushan Hosts Chavi Bar-Zeev", description: "What happens when you take a matchmaking system thousands of years old and try to run it in an age of self-fulfillment and individualism? Chavi Bar-Zeev, a rebbetzin, bridal instructor, former high-tech professional, and holder of a master's degree in philosophy, lays her cards on the table: why the institution of marriage is in trouble in the face of the crisis of modernity, what young Haredi brides really ask once the door closes, why Haredi society still treats blended families as taboo even as the dam has broken in the wider religious public, and how to combine a marriage contract built on mutual interests with a genuine covenant built on shared values and emotional communication. A conversation about matchmaking in a new era, bridal guidance versus groom guidance, and the core value men need to bring to the table when the burden of earning a living falls on women." },
  "pzmeGnmSVHg": { title: "From Disney to the Holy of Holies: Why Oria Mevorach Calls Herself a \"Fanatical Romantic\"", description: "How does a girl raised on Disney princess stories grow up to become one of the most influential voices in the conversation on sexuality and Judaism? Oria Mevorach shares her personal story and the deep motivation behind her book What Do You Seek. In a fascinating conversation with Esty Shushan on the podcast Haredit Meduberet, the two dive into the connection between romantic partnership and closeness to God." },
  "hqRBPgrlcuQ": { title: "Karlin, Breslov, Cinema | Esty Shushan Hosts Mindy Erlich", description: "The move of filmmaker and attorney Mindy Erlich's family from the Karlin Hasidic dynasty to Breslov wasn't just a shift in group identity, it was the first crack in what had seemed self-evident. Moving between two different Hasidic worlds gave her the ability to question, to compare, and to recognize that the framework isn't the single, singular thing it appears to be from the inside. In this episode of Haredit Meduberet, she tells Esty Shushan about her childhood in Jerusalem's Geula neighborhood, about the moment that stability first cracked, about moving within Haredi society and about early marriage, and about her acclaimed film Pink Lady, which shone a spotlight on a silenced phenomenon. And her suggestion to those who complain there's too much film and television being made about Haredim: \"Drink a glass of water.\"" },
  "wFHleu2AA24": { title: "The Real Reason for Leaving Shas, and the Critique of \"Mr. Security\", According to Yigal Guetta", description: "\"I didn't leave Shas, Shas left me.\" Yigal Guetta opens up about everything in a personal, unguarded interview.\nFrom the famous story of the wedding that shook the Haredi world, to unrestrained criticism of Benjamin Netanyahu and the security establishment's failed conception. Guetta explains why he refuses to stay silent, why Haredi politics is afraid of the truth, and why he calls Netanyahu \"the most failed prime minister in the history of Israel's security.\"" },
  "KRGaBBJ7NLo": { title: "\"Anyone Who Isn't Learning, Report to the Induction Center!\": Yigal Guetta Criticizes the Haredi Leadership", description: "After October 7th, something has to change. Yigal Guetta talks about the bleeding wound of Israeli society: Haredi enlistment.\nIn this video, Guetta sharply criticizes the Haredi leadership for failing to grasp the gravity of the moment, explains why every yeshiva student who isn't actually learning should report to the induction center tomorrow morning, and shares his feelings as a father whose son served three years in the IDF. Is equal sharing of the burden merely a political issue, or an existential need?" },
  "lXa8PtO4dqU": { title: "Where Are the 20 Seats? Yigal Guetta: Has Shas Betrayed the Traditional Public?", description: "Shas was founded to \"restore the crown to its former glory,\" but has it forgotten the people who built it? Yigal Guetta analyzes Shas's transformation from a social-traditional movement into a \"black-and-white\" party disconnected from the periphery.\nIn a sharp conversation, he explains why the traditional public no longer feels at home there, why the government has failed to address the periphery's deep-rooted problems, and what residents of Kiryat Shmona and Beer Sheva are really missing." },
  "_eNxpWEOBsU": { title: "\"The Sephardi Yeshivas Have Overtaken the Ashkenazi Ones\": Yigal Guetta in an Unprecedented Conversation on Racism and Education", description: "Have Sephardi yeshivas become the new gold standard? Yigal Guetta, in an open conversation with Esty Shushan on the podcast Haredit Meduberet, doesn't hold back his criticism of institutional racism in Haredi education.\nIn this video, Guetta explains why Sephardi parents who insist on Ashkenazi institutions only perpetuate the discrimination, reveals what happened to him when he was called \"Frank\" (a derogatory term for Sephardi Jews) at a Litvish yeshiva, and states flatly: \"The selection process in seminaries has to stop.\"" },
  "j2-OcWg8ivY": { title: "Who Will the Modern Haredim Vote For? | With Tehila Gadu", description: "In this episode of Haredit Meduberet, Esty Shushan talks with Tehila Gadu, a researcher of Haredi society and a Talmud teacher, who chooses to define herself first through the study hall and only afterward through academia.\nThrough a distinction between a practical stream seeking to integrate without challenging the system, and an ideological stream trying to recalculate the boundaries of Haredi identity from within, a complex picture emerges of a fractured public, one that isn't even necessarily praying in the same synagogue, let alone voting as a single bloc. The conversation touches on the gap between a shift in consciousness, the desire to upgrade one's quality of life, and actual political behavior; on the question of representation for Haredim integrating into Israeli public space; and on the social costs of that migration on the way to integration.\nBetween Talmud study, the standing of Haredi women, and the study of authority and power structures, it turns out that the question of who \"the new Haredi\" really is, is really an attempt to find out whether a stable identity is forming here, or just a collection of individuals, each trying, in their own way, to find their place." },
  "CD9RkuoMLCI": { title: "Corruption That Crosses Every Line! | From the Episode with Naomi Avraham", description: "In this clip from the episode, Naomi Avraham courageously opens up about the growing corruption in Haredi society. What do you think, is there reason to be afraid?" },
  "qJCi981rpaE": { title: "Essentialist Racism in Haredi Society! From the Episode with Naomi Avraham", description: "Let's understand the way racism takes shape in Haredi society! From the episode of Haredit Meduberet with Naomi Avraham" },
  "DWqdFKatm5c": { title: "Do Secular Israelis Really Want to Separate Religion and State? | Esty Shushan Hosts Yair Asulin", description: "In this episode of Haredit Meduberet, Esty Shushan speaks with Yair Asulin, novelist, thinker, and strategic consultant to companies and organizations, about ideas from his latest book, How We Are Reborn. Among them: the possibility that Ben-Gurion didn't \"cave\" to the Haredim, as the common narrative goes, but actually sought to control Judaism through the state and thereby rein it in.\nWas, and is, the entanglement of religion and state a religious interest or a secular one?\nWhy does it seem that precisely in an era when Judaism has more power and resources than ever, its intellectual voice is diminished and devalued?\nThrough a conversation spanning Haredi society, religious Zionism, messianism, progressivism, the humanities, and artificial intelligence, further questions arise: Does religious Zionism still generate ideas and thought for the nation as a whole? What's the connection between messianism and progressivism, and does the derangement attributed to both signal the breakdown of the old language? What happens to a world in which old authorities, from politics to academia, are steadily eroding?\nAnd are we at the end of the political era as we've known it?" },
  "RXdFa9ghP4U": { title: "Who Did You Call a 'Frenk'? | Esty Shushan Hosts Prof. Nissim Leon", description: "In this episode of Haredit Meduberet, Esty Shushan speaks with Prof. Nissim Leon, one of Israel's leading scholars of religion, ethnicity, and class, and the scholar who coined the terms \"the Mizrahi middle class\" and \"soft Haredism.\" Drawing on his research into Shas, the yeshiva world, and Ashkenazi-Sephardi relations within Haredi society, he offers a historical, sociological, and political perspective.\nHow did secular academic policy shape the rise of the Haredi \"society of scholars\"? What was the revolution local Sephardi rabbis brought about in building Haredi political power? And if Litvish identity isn't a geographic ethnicity but an ideology that united many Ashkenazi communities around a shared outlook, where did it go wrong with Sephardi Jews? What does the professor mean when he speaks of \"the betrayal of the Litvaks\"?" },
  "yEP0VrSLwhA": { title: "Spiritual Abuse Inside the Home | Esty Shushan Hosts Tzipi Levy", description: "Spirituality is supposed to be a space of meaning, comfort, and connection. But what happens when it becomes a tool of control?\nIn this episode of Haredit Meduberet, Esty Shushan speaks with Tzipi Levy, a social worker specializing in welfare services in Jerusalem and one of the people who helped coin the term \"spiritual abuse\" within the therapeutic context of couples' and family relationships.\nWhen does religious authority cross the line into stripping away someone's autonomy? How is the language of sin, fear of Heaven, and the World to Come used to instill fear, guilt, and shame? Is this a gendered phenomenon, and are men affected by it too? How does spiritual abuse become part of a broader pattern of emotional, financial, or sexual abuse? What are the patterns and psychological costs of harm committed in the name of Heaven, where does communal responsibility for preventing it come in, and how can spirituality itself serve as a tool for healing and growth?" },
  "5BYvkVjmjSo": { title: "On Hypocrisy | Esty Shushan Hosts Naomi Avraham", description: "In this episode of Haredit Meduberet, Esty Shushan hosts Naomi Avraham, an attorney and forensic accountant who was raised and educated within Haredi society and went on to work in the civil service. The conversation dives into the story behind Naomi's series of posts titled \"On Hypocrisy\", in-depth investigations that broke out of a niche, silenced discourse and became a scathing indictment of an entire system." },
  "_zxcR_qWs20": { title: "Any Chance of Drafting the Shababnikim? | Esty Shushan Hosts Eliran Malka", description: "Since October 7th, the question of Haredi identity, army service, and Israeli partnership can no longer be avoided. In this episode of Haredit Meduberet, Esty Shushan hosts Eliran Malka, creator of the hit TV series Shababnikim and the film The Unofficial Ones. Malka talks about the responsibility of a creator in a time of national rupture, about the yeshiva-student characters now caught at the center of the national divide, and about the expectation to become \"the spokesman for the community\" at the very moment of crisis with religious Zionism and the Israeli public. What happened to Gedalia and his friends after October 7th? How do expectation and disappointment toward Haredi society play out? And can a character like Dvora, the female Haredi Talmud scholar, actually exist in Haredi reality, or is she an import from the religious-Zionist world?" },
  "PmBQlwYkMLg": { title: "A Working Woman - Who Does the Money Belong To? Esty Shushan Hosts Sari Kreizer", description: "A woman works, earns, builds a career. The seemingly simple question of who the money belongs to turns out to be a Talmudic issue the sages grappled with. In this episode of Haredit Meduberet, Esty Shushan hosts Sari Kreizer, and the two open with a joint study of the sugya \"the earnings of a woman's hands belong to her husband,\" trying to understand what happens to an ancient text when the realities of life change at their foundation, and questioning whether women's access to the Gemara is a right or an obligation.\nSari Kreizer, who studies and teaches Torah, is the CEO and co-founder of the Hineni association for the community, one of the leaders of the \"Lo Tishtok\" (Don't Stay Silent) movement, and works in high-tech. The conversation touches on Haredi women in the workforce, the Jewish obligation of a husband to support his wife as a form of insurance for her, questions of contemporary morality and justice, and breaking down the walls of silence around sexual abuse in the community." },
  "DdBTQqP_q88": { title: "Romance, Sexuality, and Holiness | Esty Shushan Hosts Oria Mevorach", description: "Romance, sexuality, modesty, and holiness have long become a cultural battleground. Between a discourse of total freedom and a discourse of prohibition, shame, and fear, something of our ability to speak honestly about the body, love, and connection has been lost. A single Knesset conference on the practice of shomer negiah (refraining from physical contact before marriage) only surfaced a deeper question: can a sane conversation about healthy sexuality even be held, without threatening those wary of religious coercion and legislation, and without erasing religious language itself?\nIn this episode of Haredit Meduberet, Esty Shushan hosts Oria Mevorach, author, halachic advisor, editor-in-chief at Maggid Books, and founder of the Afarkeset Institute. A conversation about religious puritanism and repression, about religious feminism with its own stars, and about romance worn down both in the name of sexual freedom and in the name of modesty values." },
  "pooufIFYPBg": { title: "Who Gave You Permission to Speak? | Esty Shushan on the Interviewee's Bench", description: "Usually she's the one asking the questions, this time, she's the one answering them. Sarah Yanetz, Haredit Meduberet's researcher and producer, a social worker and social-media professional, puts Esty Shushan in the interviewee's chair for a conversation about the spectrum between conservatism and innovation." },
  "w0djEfroROk": { title: "Sephardi Yeshivas Are Overtaking Ashkenazi Ones | Esty Shushan Hosts Yigal Guetta", description: "\"Shas left me, not the other way around,\" says former MK Yigal Guetta in a candid conversation with Esty Shushan, pointing to the dramatic transformation the movement has undergone: religious radicalization and the abandonment of the traditional Mizrahi public that was once its beating heart.\nIn this episode of Haredit Meduberet, Guetta takes us through the stations of his early life in Kiryat Shmona, up to his move into the Litvish Haredi world via the Magen HaYeled yeshiva in Bnei Brak. He speaks about his public and media work, addresses painfully the racism within educational institutions, and asks a burning political question: is there room for a new political home for Israel's believing and traditional public?" },
  "D0N0vlmEEv8": { title: "One Joke Outweighs a Hundred Rebukes | Esty Shushan Hosts Uri Zeitlin", description: "In a black kippah and white shirt, Uri Zeitlin takes the stand-up stage and isn't afraid to touch Israel's hot-button conflicts from a distinctly Haredi angle. In this episode of Haredit Meduberet, he shares with Esty Shushan his childhood in a large family, his family's ties to the hardline Jerusalem Faction (the Eda Chareidis' \"Peleg Yerushalmi\"), and the dropout yeshivas and gossip hotlines (\"news lines\") he passed through along the way. Where are the limits of humor? What jokes get told at the Slabodka summer camp, and why can't he bring himself to laugh at jokes about religious-Zionists (mockingly nicknamed \"Mizrachnikim\")?" },
  "FOIn4iT-YmM": { title: "Secular Husband, Haredi Wife - Peace in the Home | With Ami and Avital Bar'am", description: "What happens when the great religious-faith rift walks in the front door? When one spouse changes course, becomes religious, or leaves the fold? Is the rabbinical courthouse the only option, or is there a way to build a life together as a mixed couple? What happens with the children, and who pays the price for the other's spiritual journey?\nIn this episode of Haredit Meduberet, Esty Shushan hosts the couple Rabbi Ami and Avital Bar'am, founders of the Hitkashrut Association, Believing Together, who themselves went through the transition from a secular relationship to a religiously mixed one, until they found common ground and turned their own story into a support framework for couples where one partner's way of life changes midway through life. And what can all this teach us about Haredim, religious, and secular Israelis sharing life on this land?" },
  "Gq6vk6QDJ1E": { title: "Haredim on the Psychologist's Couch | Esty Shushan Hosts Noam Green", description: "What happens when the Haredi psyche asks for help in a world where words like \"depression,\" \"anxiety,\" or \"trauma\" still carry a troubling stigma? In this episode, Esty Shushan hosts Noam Green, a neuropsychologist in training, content creator, and host of the podcast \"Souls and Their Absence.\"\nTogether they step into the space where professional therapy meets community and God, where women have no time to care for themselves, and where community power-brokers can end up managing an individual's mental health.\nEsty and Noam also return to their shared hometown, Haredi Safed, to the city's baal teshuva (returnee-to-religion) community, and to its influence on Noam's clinical work and public activity." },
  "KYivJVpg27o": { title: "What Do Yated Ne'eman and Haaretz Have in Common? | With Dov Eichler", description: "Amid the escalating tension between Haredi and Israeli society, Dov Eichler, a media figure raised in the Haredi world and the Belz Hasidic dynasty, feels that Haredi society has become a perpetual scapegoat.\nEichler, who grew up in a family of 14 children in an outspokenly political household, prefers to see himself as someone raised in the sector rather than as Haredi, a framing that gives him the freedom for internal media criticism. But he always keeps an eye on his back, wary that his internal criticism might be used as a weapon against the whole community.\nIn this densely packed episode of Haredit Meduberet, Dov and Esty try to understand what happens when someone stands right on the fault line: demographic anxieties, tribal loyalty, and the paradox of the change Haredi society badly needs, a change that puts the survival of Haredi identity and culture itself in question. And what \"ordinary\" Israelis need to do to understand the Haredi sense of persecution." },
  "w3ErMane6d0": { title: "The Battle for the Hill - Ponevezh | With Eli Beitan", description: "How a real-estate dispute between two brothers-in-law over the inheritance of a yeshiva in Bnei Brak turned into a violent, passionate struggle over identity, leadership, and the very essence of Haredi life.\nIn recent years, two rival yeshivas have operated out of the same study hall at Ponevezh. Two leaderships, two narratives, and two competing versions of who carries the tradition forward and what \"authentic Haredi identity\" even means. In November 2025, a dramatic arbitration ruling by retired judge David Hashin sought to put an end to the dispute.\nIn this episode of Haredit Meduberet, Esty Shushan hosts Eli Beitan, a Ponevezh alumnus, journalist, and comedian. Together they look out over the hill that became a symbol:\nHow did the Ponevezh brand keep its prestige despite incidents of violence and the humiliation of its rabbis?\nWhy is the name \"Ponevezh\" worth more than the land itself?\nAnd what does this crisis reveal about Haredi society as a whole?" },
  "SQ-pDX5MHQ4": { title: "Second Generation to Return - America | With Tirtza Bloch", description: "In this episode of Haredit Meduberet, Esty Shushan speaks with Tirtza Bloch, a second-generation daughter of American baalei teshuva (returnees to religious observance), a copywriter, and a companion to women going through divorce.\nThrough her personal story, we enter the wave of religious return of the 1970s: American flower children searching for meaning who landed in the ascetic Litvish Haredi world. Tirtza herself was born already in Israel, inside an attempt to erase the America that had come before, an attempt that produced a generation with a split identity: a home carrying silenced remnants of American culture, set against Israeli Litvish Haredi life, and an ongoing sense of \"being caught between two worlds.\"" },
  "FUIgJ0vDl2Y": { title: "Meeting ZAKA, in Life | With Motti Bukchin", description: "From the first time he encountered death as a young Nadvorna Hasid, through the Meron disaster, to the blood-soaked scenes of the Simchat Torah massacre, Motti Bukchin, ZAKA spokesman and volunteer for three decades, opens a window onto a world most of us prefer to repress.\nIn this episode of Haredit Meduberet, he tells Esty Shushan about the moment his body gave out after weeks of horror, about the psychological toll on thousands of volunteers who returned from the field and broke down, about the faith that keeps them going, and about the shadow of Meshi Zahav, the organization's founder, who fell from grace and left behind an entire organization to grapple with the rupture and its aftermath.\nHe shares the volunteers' dark internal humor and talks about ZAKA's women volunteers, and about how the volunteers' wives cope with the weight of horror their husbands carry home." },
  "03A5kdl-PNk": { title: "The Red Line - The Haredi Education System | With Feigy Cohen", description: "Feigy Cohen, a former teacher, supervisor for the Haredi school district, board member, and director of research and development, describes how she left the teachers' room at a Beit Yaakov school, went back for more degrees, and moved into academia and the Ministry of Education in order to change the system from within. In this conversation with Esty Shushan, she speaks candidly about painful moments: threats made against children in cheder, the isolation of standing up to powerful institutions, bureaucracy dressed up as ideology, and her stubborn insistence on building programs for gifted children when everyone told her that was \"a rich person's problem.\" This is an episode about the red line in Haredi education: who draws it, and who defends it? About the economic pressures on kollel families and their costs, the state-recognition (\"mamach\") track, core-curriculum requirements, and student dropout. Above all, it's a personal and family journey, from the Litvish bubble to the heart of efforts to reform Haredi education." },
  "21GT6IJ5fX4": { title: "From the Yeshiva Study-Stand to the Business Desk | With Nati Tucker", description: "What is the role of journalism in an era when \"truth splits into competing herds\"?" },
  "-MA7qV3wfh4": { title: "When the Framework Squeezes | On ADHD and Neurological Difference, with Dr. Chaim Dayan", description: "Attention disorders touch on education, medicine, sociology, psychology, philosophy, and Jewish thought alike. In this episode of Haredit Meduberet, Esty Shushan speaks with Dr. Chaim Dayan, a clinical social worker, a reserve mental-health officer in the IDF, and chairman of the Attention Institute, about what happens when educational and social frameworks bear down on people whose minds work differently from the existing standard. Why is it so hard to diagnose ADHD in girls? And how does a duality play out in yeshivas, which impose a rigid, uniform framework on the one hand, yet apply much softer standards for what counts as excellence and success on the other? The conversation touches on the tension between collectivism and individualism, the inflation of diagnoses, cultures and personality types that are \"round\" versus \"square,\" and the bigger question: is difference a disorder to be fixed, or an opportunity to see society, and ourselves, a little differently?" },
  "P13B80XsYFw": { title: "What's the Story With the Ger Hasidic Dynasty? | With Attorney Neta Katz", description: "Neta Katz, an attorney and social activist, was raised and educated within the Ger Hasidic dynasty and went through the full Gerrer life track, cheder, yeshiva, an arranged match, and marriage at a young age. In this episode of Haredit Meduberet, he retraces with Esty Shushan the experiences that shaped his world, and discusses the community's mechanisms of discipline and obedience, how they penetrate the psyche, shape the family and one's personal identity, and ultimately translate into political power that leaves its mark on Haredi society and on Israeli society as a whole. The conversation with him is a personal and public journey: from the Gerrer home to his legal and social work today, an attempt to expose the costs alongside the achievements, and to ask broad questions about freedom, faith, and power." },
  "VjV8t_6Pty0": { title: "A Black Kippah and an Army Uniform | With Moshe Frigen", description: "A Haredi yeshiva that looks from the outside like any other, black suits, a fixed study schedule, pages of Gemara. But beneath the surface, something different is happening: a connection, far from taken for granted, between Torah and action, secular studies and military service, treated as the ideal, not a compromise. Young men raised in the Haredi yeshiva world are choosing to expand their identity, to become part of the Israeli story, without giving up either the depth of their learning or their Haredi identity.\nIn this episode, Esty Shushan speaks with Moshe Frigen, CEO of the Derech Chaim network of Haredi hesder yeshivas (combining Torah study with military service), about what daily life looks like in such a yeshiva, why top students are pursuing both an academic degree and army service, and what this says about a new generation seeking to dismantle the old boundary between the sacred and the secular, and forge a new kind of rabbinic-Torah authority." },
  "xPO0-pybMNg": { title: "The Secular Israelis Who Invented the Haredi-Meter | With Penina Poyfer", description: "As Haredi demographics came to be seen as a threat in the eyes of the state's policymakers, \"correction programs\" for Haredim were built. Research institutes and secular scholars of Haredi society took a central role in shaping policy, with the guiding approach being to invest in the Haredi mainstream: to partner with political and communal gatekeepers, while at the same time silencing the revolutionary voices from within, the ones demanding real, deep reform. The result, predictably, wasn't reform at all, but a worsening of the problem." },
  "YR9UN2XrZrM": { title: "Judaism, Power, and War | With Michael Mankin", description: "Is the Jewish people's current test a test of power? After two thousand years of exile, during which the prevailing concept of security was trust in God, today's dominant concept of security is military, force and might, and the disputes now center on dosage and intensity. In this episode of Haredit Meduberet, Michael Mankin, a founder of the faith-based Israeli left, speaks with Esty Shushan about the way nationalism, as a secular movement, absorbed ideas of power and control into rabbinic Judaism, and about how those ideas have shaped messianic thinking. He talks about his military service in the Golani Brigade around Nablus, about the black knitted kippah, and asks, together with me, whether it's still possible to speak of morality, even after the horrors of October 7th." },
  "V_l8zsJvD3I": { title: "Mid-Movement - Body, Dance, and Censorship, With Elisheva Razvig", description: "Elisheva Razvig dances at more than one wedding, and has no intention of apologizing for it. Having grown up straddling the Jerusalem fault line between religious-Zionist Kiryat Moshe and Haredi Givat Shaul, between East and West, between the Haredi Zarkor book series and novelist Meir Shalev, between the settlement of Migron and Tel Aviv, she is an unconventional creator in the world of dance, opening yet another door for personal expression by religious and Haredi women through body and movement. In this episode of Haredit Meduberet, she tells Esty Shushan about the Haredi teacher who taught her to dance, about wanting to ask questions through dance and running into censorship, about women-only performances and the questions of gender separation they raise, and about the position of a kollel wife within religious Zionism, and what that means for the question of military service." },
  "1uXnTc-6f3g": { title: "Drafting Men, Erasing Women | With Michal Gera Margaliot", description: "A few years ago, a Haredi singing event in Afula featuring Haredi music star Motti Steinmetz made national news. The Israel Women's Network, then headed by attorney Michal Gera Margaliot, led the fight that put gender segregation at the center of public debate. Since then, questions about women's visibility and their place in public space have only grown sharper, and may even have pushed us backward. Is there a connection to a progressivism that has grown more extreme, and to the silence of international women's organizations in the face of Hamas's crimes of rape?" },
  "MwvgyvYdCKA": { title: "Haredi Society on the Operating Table - An Outsider's View, With Dr. Neri Horowitz", description: "With a deep, intimate familiarity with Haredi society, from the level of the individual, through its subgroups, communities, and ideological worldviews, to the systems that run it, Dr. Neri Horowitz, a scholar of Haredi society, gives no free pass to the subjects of his research. In this episode of Haredit Meduberet, he talks with Esty Shushan about the insights, stories, and experiences of someone who, from a young age, wandered the synagogues of Jerusalem trying to decode the Haredi code.\nFrom the influence of Shas and Mizrahi identity, through the education system as both brand and business, to an analysis of the phenomenon of leaving the faith, leadership failures, and the struggle over military conscription. An intense conversation, longer than usual, that connects hard data with vivid stories from the field." },
  "Y7J-EyPeWpY": { title: "Where There Are No Leaders, Lead the Way | With Liat Malka", description: "Liat Malka, the first Haredi woman to serve as a member of a religious council, tells Esty Shushan about her path from the Haredi periphery to public life.\nFrom the home she grew up in, caught between the sacred and the secular, through becoming religiously observant at 19, to public battles against the failures of the Haredi education system, and on to senior positions in government ministries and dealings with Shas's Council of Torah Sages. Liat didn't wait for an invitation, and she didn't wait for permission, either.\nA conversation about identity, calling, and a female leadership that challenges the rules." },
  "jWDZFt0RtA0": { title: "Make Room for the Tribe - Who's In? Who's Out? | With Chen Artzi Sror", description: "The dramatic and painful events of recent years have exposed a reality we didn't want to believe existed, the social rift has become an existential threat, and through it the old legends of the Temple's destruction have never felt more relevant. Different languages, conflicting beliefs, fears that aren't shared, and deepening currents of separation are threatening the Third Temple.\nIn this episode of Haredit Meduberet, Esty Shushan speaks with Chen Artzi Sror, journalist and researcher, following her book Tribe of Brothers, written with Amichai Danino after October 7th.\nThey discuss the collapse of the ethos of statehood, the trauma of the \"melting pot\" that ended up producing division instead of unity, the place and responsibility of the Haredi tribe within the map of the Zionist covenant, and where traditional Israelis fit into this tribal division.\nAnd is it still possible to build solidarity, real, clear-eyed solidarity that leaves no one out?" },
  "_NiHKL83Wkw": { title: "Lovesickness - A New Look at Haredi Identity | With Menachem Navot", description: "In this episode of Haredit Meduberet, Esty Shushan hosts Rabbi Menachem Navot, author of the book Haredim el Devaro (Trembling at His Word), for a conversation about the essence of Haredi identity, not as a sociology or a reaction against secularization, but as a \"lovesickness,\" a total religious passion for fulfilling the word of God." },
  "lcUUVUR2LzA": { title: "Truth in Advertising, Creative Work, Spirit and Soul | With Yossi Sabag", description: "Don't expect an episode about how to sell products to Haredim, you can get that from the sector-specific ad agencies. This is a conversation about a man who lives right on the seam: between Bnei Brak and Tel Aviv, between Beit Mat's and Pardes Hana, between a campaign for Shas and a brief from mainstream Israeli brands. Yossi Sabag, copywriter and creative, is on a journey of belonging, disconnection, and reconnection." },
  "0LqTyROagPs": { title: "I Study Gemara - Deal With It! With Didi Shor", description: "Didi Shor, educator, researcher, intellectual, and a Chabad-trained Torah scholar, doesn't apologize for the independent religious stance she's developed, doesn't bend to double standards, and isn't willing to shape herself to fit others' expectations or discourse.\nIn this episode of Haredit Meduberet, Didi shares candidly with Esty Shushan her experiences as a Haredi Torah scholar, \"devoutly religious through and through.\" She talks about how female religious devotion can sink a match in the shidduch world, why scholarship is an asset for men but \"too much\" for women, and why the common insult \"bitter\" is actually a sweet drive toward action.\nDidi, like other women unwilling to keep their heads down, to ignore the locked bookcase in the room, and to accept thousands of years of female silence, is turning that \"bitterness\" into a new spiritual proposition." },
  "DW9KIRuq_lw": { title: "How Do You Turn Otherness Into a Home? With Eli Dan", description: "What happens to a child born into a family that no existing mold could contain?\nWhat happened to the boy who drifted through Laderman, found his footing at Ponevezh, and ultimately managed not just to belong, but to actually feel it?" },
  "IylE2sn8Vq8": { title: "A Lesson in Responsibility: Torah, Morality, War | With Rabbi Refael Kreizer", description: "On October 8, 2023, with the fighting still raging and the blood of our brothers and sisters not yet dry, Rabbi Refael Kreizer published a pointed post calling on yeshiva students to step up, not just to sit and study, but to bear the burden, in body and soul, as the ideal course of action, not merely a fallback.\nRabbi Kreizer grew up at the heart of the Litvish scholarly elite, at the Chevron Yeshiva. In this conversation on the Haredit Meduberet podcast, he tells Esty Shushan about his worldview, speaking about a moral rupture, about a Torah that demands connection to life itself, about the question of conscription, about religious courts, about leadership, and above all, about what happens when we forget why we were given the Torah in the first place." },
  "zVXHLREeuiU": { title: "When Haredim Began Studying Themselves in Academia | With Dr. Nechumi Yaffe", description: "She started out as a Haredi teacher writing a history curriculum for Haredi girls, and found herself at the National Library searching for sources. From there, a love of knowledge and a drive for social justice would carry her into the university and toward the unique body of knowledge she now builds by relentlessly mining data on Haredi society and its character." },
  "g40_wwKdO_Y": { title: "I Never Wanted to Rebel | With Hania Brodbecker", description: "Hania Brodbecker, raised in the Ger Hasidic dynasty, never wanted to go to war, never wanted to smash down walls or rebel against convention. She may have harbored some repressed dream of getting a driver's license, but mostly she just wanted to raise her son, Ari, who was diagnosed on the autism spectrum, within a strictly Haredi, mainstream educational framework. Along the way, she discovered no such framework existed. In her documentary The Three of Us, Brodbecker chronicles her and her husband's migration in search of a school for their son, moving from the Haredi world into an Israeli mainstream that doesn't always welcome them, a migration that is geographic, and also one of identity, culture, and existence. In this episode of Haredit Meduberet, Hania tells Esty Shushan about the triangle of Bnei Brak, Elkana, and Tel Aviv, about a way of life rewritten from scratch, about sidelocks cut off in tears, about creating art across a cultural divide, and about being an immigrant within your own country." },
  "SPjNiPAcuAE": { title: "The Haredi Revolution That Predated MeToo | With Avigail Hilberon", description: "Years before #MeToo triggered a global reckoning, the Haredi community was already cleaning house internally. One post by Avigail Hilberon, a young Haredi woman working in high-tech, about feeling safe, or not, unleashed a wave of disclosures from survivors, exposed a longstanding conspiracy of silence, gave rise to a movement, and above all, produced a deep shift in awareness.\n\nChaim Walder, Yehuda Meshi-Zahav, these are only some of the names that surfaced as serial abusers, men with power and connections, whom Haredi society ultimately denounced, though not without a fight.\n\nIn this episode of Haredit Meduberet, Esty Shushan talks with Avigail, founder of Lo Tishtok ('Won't Stay Silent') and co-director of Hanini, about the road she traveled, its costs and challenges; about the complicated feminist identity awakening in a young kollel scholar's wife; about social media as a battleground for change; about the rabbinic leadership's silence, and about whether abusers can ever truly repent and be rehabilitated." },
  "a6WLKif-QkU": { title: "Money, Power, and Property Tax: Bnei Brak's Opposition | Yaakov Vider", description: "Bnei Brak has an opposition. One person. Yaakov Vider, a city council member for Likud, is its sole opposition representative, the only one with no rabbinic title attached to his name, no budgeted office, and who had to fight just to get his room cleaned. To his right, Bnei Brak's other opposition is the extremist Jerusalem Faction.\n\nIn a city that has run for decades without a dissenting voice, Vider chooses to stand against the consensus led by Shas and Degel HaTorah. Bnei Brak, a city split between 'scholars and providers,' between educational institutions and a kollel-scholar population on one side and gleaming office towers on the other, isn't just a city, he argues; it's a system. Vider, a Mir yeshiva graduate, a lawyer, and a longtime resident, contends that this system perpetuates poverty and dependency, and runs a city plagued by poverty, filth, crumbling infrastructure, and a rat infestation." },
  "iMdIHvOpi-Y": { title: "Don't Ask Her How She Manages | With Shira Narinsky", description: "Shira Narinsky is a 25-year-old Haredi woman. She lives in Bnei Brak, is pursuing a master's degree in Middle Eastern history, develops learning materials for the Ministry of Labor, surfs in her spare time, and lectures on willpower.\n\nShe doesn't want to be called inspiring, and she has no interest in explaining her choices so you'll understand them. She simply refuses to fit herself into the prosthetic identity society straps onto anyone who deviates from the mold.\n\nIn this episode of Haredit Meduberet, Esty Shushan talks with Shira about strange matchmaking encounters, stares that never let up, the unlikely schools she attended, volunteering for an organization that helps amputees, a family of ten children forever changed by tragedy, a fractured sense of identity, being second-generation to parents who returned to religious observance out of naive conviction, and the moment she found herself turned into a first-grade classroom's petting-zoo attraction at Beit Yaakov.\n\nEveryone carries their own particular burden through life. Shira carries hers, lightly, with humor, and with faith." },
  "4VMHkLlJj_E": { title: "Breaking Free From Bondage, Beating Addiction | With Yaakov Yisrael Amar", description: "Breaking free from bondage, beating addiction, how does Haredi society deal with addiction? A firsthand account." },
  "202FS5O5e1E": { title: "Being Bnei Brak's Guy Pines (Israel's Top Gossip Reporter) | With Simi Hershkop", description: "Orphanhood, pain, humiliation, and ostracism, the backstory behind DosLives, the Haredi world's biggest gossip page. Simi Hershkop, the page's founder and the phenomenon behind it, speaks with Esty Shushan on Haredit Meduberet with striking candor about a hard childhood on the margins of the community; about what happened to her at Beit Malka, the Hasidic school she attended; about the need to be seen and heard that led her to open an Instagram account; about Hebrew replacing Yiddish, her mother tongue; and about the less glamorous moments behind the campaigns and product launches." },
  "Uv_JWt-NbSU": { title: "Between Propaganda and Outreach: What Does Haredi Advocacy Look Like? With Eli Adler", description: "Between propaganda and outreach: what does Haredi public advocacy actually look like?\n\nIs it a genuine attempt to open dialogue, or propaganda meant to justify negative phenomena? How does a Haredi person explain to himself the hostility directed at his community? And do advocates and media figures whose own lives contradict the values they preach know they're doing it?\n\nIn this episode of Haredit Meduberet, Esty Shushan talks with Eli Adler, a Haredi lecturer, cross-cultural mediator, and reserve major, about the dilemmas, contradictions, and gaps facing someone standing right at the seam between worlds.\n\nWe talked about the precarious position in which every Haredi person becomes an unwilling spokesperson for an entire community; about the built-in conflict with religious Zionism over the draft; and about whether religious-Zionist advocacy actually succeeds in persuading Haredim.\n\nYouTube channel: https://bit.ly/4gKBheD" },
  "1Yaho1uHFqs": { title: "Her Torah, Her Calling | With Orthodox Rabbanit Shira Marili Mirvis", description: "She leads a community, rules on questions of Jewish law, and stands almost alone against a world that doesn't quite know what to make of her. Rabbanit Shira Marili Mirvis, who has devoted her life to Torah and halacha, leads a congregation in the settlement of Efrat and sees her role as a mission on behalf of every woman throughout the generations who was denied that possibility.\n\nWhat does it mean to be an Orthodox rabbanit? What price does she pay along the way? And how does she balance loyalty to tradition and halachic ruling with the need to make room for women, in a world that once held that Torah teachings should sooner be burned than taught to a woman?\n\nAn eye-opening episode of Haredit Meduberet with Esty Shushan, on Torah, leadership, and boundaries being redrawn in a world still owned exclusively by men." },
  "U_la-TMwsmA": { title: "I Came to Interview, I Left Interviewed | With Racheli Meshulam Solomon", description: "There's exactly one woman who has managed to push Esty Shushan out of her comfort zone in the interviewer's chair on Haredit Meduberet.\n\nHer name is Racheli Meshulam Solomon, an actress, a producer of women's parties, a member of the improv theater trio Kontserta, a graduate of Nivcharot, a social activist, and formerly a political operative on Naftali Bennett's staff. Racheli is also Esty's close friend, the kind who walks into her house without knocking and helps herself to whatever's on the stove. Esty expected Racheli to answer all the questions, but found the tables turned, and that she herself would now have to start answering some too. An episode that wanted to be a Purim episode." },
  "hZWPbTodyjA": { title: "The New Haredi Society, A Movement Without a Banner? | With Rabbi Dr. Benayahu Tevila", description: "The 'new Haredim' are rewriting the rules with their push to combine Torah study and work, but what values actually guide them, both in life and in the new educational track they've built, known as Mamach (the state-recognized Haredi education stream)? Where the old-guard Haredi world proudly flies the flag of separatism and full-time Torah study as its sole occupation, the new Haredi stream has neutralized the old fears of secular education, employment, and army service, yet it still hasn't articulated the core values that would justify its existence as a distinct stream of education and community." },
  "8FRIW0dMhMU": { title: "Try Running a Haredi City | With Dr. Aliza Bloch, Former Mayor of Beit Shemesh", description: "Dr. Aliza Bloch, who actually comes from the religious-Zionist world, walked straight into one of Haredi society's hottest flashpoints: a city where extremism against women became a widespread phenomenon, where zealot Haredim fight modern Haredim over the character of a city whose traditional Mizrahi, right-leaning base found itself caught in a religious war alongside religious-Zionists and secular residents. In conversation with Esty Shushan on Haredit Meduberet, she talks about sound governance versus sectarian politics, about the experiment and aspiration of shared leadership in a deeply divided city, about extremist versus modern Haredi identity, about the draft law, and about what Beit Shemesh can teach us about Israel's larger conflicts." },
  "adGcq9yBgQM": { title: "A Time to Love | Sexuality, the Body, and Pleasure | With Dr. Michal Prince", description: "Between religious law and lived practice, between holiness and desire, in this episode of Haredit Meduberet, Esty Shushan hosts Dr. Michal Prince for a candid conversation about sexuality and the body in a world where modesty and holiness set the rules." },
  "CLMDkRFzbNE": { title: "A Home Shouldn't Hurt, On Divorce and Separation in the Haredi Community", description: "Haredi society places the family at the center of life, but what happens when home becomes a place of pain or violence? In this episode, Haredi social entrepreneur Peini Soknik, founder of Ba'asher Telchi ('Wherever You Go') and Red Lines, talks about navigating divorce within a community that struggles to accept broken homes, about the loneliness, the emotional and social challenges, and about turning anger and pain into action. An important, candid, and unsettling conversation about a subject that isn't always discussed, and what can be done to change that." },
  "4Gp2j6alEH4": { title: "When Ethnic Discrimination Got a Kosher Stamp! With Attorney Yoav Lalum", description: "In the summer of 2010, the Immanuel affair broke into the headlines, in which Ashkenazi and Mizrahi girls were segregated within the same school. Attorney Yoav Lalum, who led the legal battle all the way to the High Court of Justice (Bagatz), reveals what happened behind the scenes of the widely covered fight, the legitimacy mainstream Haredi institutions granted to the discrimination, the price he personally paid, and the ongoing struggle against institutionalized racism in Haredi education." },
  "MvXbgl1ca8A": { title: "Wiping Off the Filters, Episode 21 With Social Media Influencer Chani Malul", description: "Chani Malul, a social media personality with tens of thousands of devoted followers, uses her platform not only to earn a living but to raise awareness, offer social critique, and push for real change.\n\nIn this episode, in an open conversation with Esty Shushan, she reveals the personal story that led her to address sexual abuse within the Haredi community, explains how her content manages to fit into the filtered world of Instagram, and why, as far as she's concerned, none of it has anything to do with feminism." },
  "UHd4h14Z9Qg": { title: "Running From the Synagogue and Back | With Artist, Singer-Paytan, and Music Researcher Yigal Harosh", description: "Yigal Harosh is an artist, singer-paytan, and music researcher for whom synagogue liturgy, piyyutim, and Moroccan-Jewish musical tradition are inseparable from his identity and his art. In conversation with Esty Shushan, they dive into the soundtrack of his childhood, his grandmother, who prayed for his return to the synagogue in Dimona; the winter Sabbath baqashot hymns; ancient melodies (niggunim); and Jewish mysticism. A unique meeting where tradition meets contemporary art." },
  "XUX5hhu-1HQ": { title: "Haredi Identity, Messianism, and Feminism, Episode 19 With Malki Rotner", description: "Esty Shushan talks with Malki Rotner about the axis between exile and redemption as reflected in this moment in time, and about the influence of messianic thought on Haredi identity. From a perspective rooted in a deeply traditional Hasidic community, they discuss the tension between traditional Haredi identity and feminist aspirations to take full part in religious life." },
  "uNEyzRuMi6c": { title: "Excommunication Among Jews, Episode 18 With Dr. Jeremy Fogel", description: "In this episode we meet Jewish figures who were excommunicated, ostracized, and branded controversial, and try to understand what led their communities to cast them out. Through the thought and stories of Spinoza, Mendelssohn, and other figures who challenged convention, we try to make sense of the challenges of our own moment." },
  "6S23WoJEI6c": { title: "Who Turns Rabbis Into Brands? Episode 17 With Mendy Gruzman", description: "In a fascinating and charged episode, Mendy Gruzman, a Haredi journalist and broadcaster on Kan Moreshet's 'Mendy Bitan,' invites us behind the scenes of the rabbinic-title industry in Haredi society. Through his critical eye, Mendy exposes the role Haredi media plays in shaping rabbis' public images and entrenching social and religious hierarchies, and offers a bold take on the mechanisms that decide who is worthy of being called a 'gadol', a preeminent Torah sage, and who stays on the margins." },
  "16fh5Mm0Nhw": { title: "Not Staying Silent Anymore, What Are You Going to Do About It? Episode 16 With Journalist Merav Sever", description: "Merav Sever, a journalist and author who grew up Mizrahi at the heart of Litvish Bnei Brak, shares her journey from the Haredi press to the mainstream Israeli media, and lays bare her rupture with the Haredi religious-political establishment and the personal cost of searching for an independent, authentic voice.\n\nSever tells Esty Shushan about her path from the traditional Haredi world into general journalism. With a great deal of pain, but also understanding and love, she speaks candidly about the rigid Litvish education that shaped her as a girl from a large Mizrahi family, about her early writing in the Haredi press under a pen name, and about grappling with singlehood in a world that sanctifies marriage. Merav traces her move into mainstream journalism, which let her step into Haredi society's back yard and tackle sensitive subjects like domestic violence and mental illness. She talks about the painful disillusionment that forced her to break social molds and pay a heavy price to find her own distinct voice in the world." },
  "t-5K4N59CyM": { title: "How Do Poor People Buy Apartments? Episode 15 With Dr. Eliezer Hayon", description: "Haredi charity flyers open a window onto a world of mutual aid alongside real financial tragedy, told in vivid, dramatic language that knows how to move hearts, and open wallets. Those same flyers raise hard questions about the economic engine that drives Haredi society, and about its dependence on community and state support to survive. Above all, there's a paradox: how does such a poor community manage to marry off its children and buy apartments, when even government benefits don't add up to explain the numbers? In this episode, Esty Shushan hosts Dr. Eliezer Hayon, a journalist and senior researcher at the Jerusalem Institute for Policy Research and one of the leading experts on Haredi society. We dive into the world of miracles, myths, and numbers behind the dramatic stories, guided by new research that asks: is livelihood really 'from heaven'? Is there room for miracles in a spreadsheet?\n\nDr. Eliezer Hayon is a Haredi researcher, sociologist, and yeshiva graduate. In new research he conducted with Ehud Prawer at the Jerusalem Institute for Policy Research, he tries to determine whether there's really a miraculous element in Haredi household economics; whether dependence on state benefits explains the numbers in the Haredi economy; and what a life of poverty by choice actually looks like." },
  "C70SDuJE-ss": { title: "Bnei Brak's Corner of Hollywood | With Pioneering Film Scholar Dr. Marlyn Vinig", description: "Dr. Marlyn Vinig is a trailblazing figure in Israeli culture, bridging the Haredi and secular worlds. As a film scholar, she introduced the phenomenon of Haredi cinema to the wider public through her books 'Haredi Cinema' (2011) and 'A Cinema of Their Own' (2020). Vinig, who founded the first acting studio for the Haredi public and developed the 'Marlena Index' for measuring women's representation on screen, works to expand the boundaries of Haredi artistic creation while preserving its values. As a baalat teshuva, a woman who returned to religious observance, and a member of the Second Authority for Television and Radio, she grapples with the challenges of identity and cultural creation in a modernizing Haredi society, while promoting feminist and creative discourse from within the community." },
  "z92hqto2iUY": { title: "A Revolution in Religious Thought! Can Science and Faith Coexist? Rabbi Dr. Michael Avraham", description: "Can science, faith, and feminism actually be reconciled? Rabbi Dr. Michael Avraham, a physicist, philosopher, and trailblazing thinker, joins Haredit Meduberet to propose a revolution in religious thought. With his singular way of thinking, he challenges the conversation about God from both sides of the divide, science and religion alike, from his claim that 'there's no such thing as a rational atheist' to positions that upend conventional religious discourse. In a challenging conversation, he calls on women to get close to the Jewish bookshelf, takes on both Haredi and religious-Zionist politics, and offers surprising answers to burning questions. As founder of 'The Third Path,' he seeks to connect moderate religious Jews to an approach that combines deep faith with modern ethics and intellectual honesty." },
  "DhWB-RqJA4M": { title: "Haredim on the Left, How Does That Work? Episode 12 With Michal Chernovitzky", description: "Michal Chernovitzky is a trailblazing figure in Haredi society and Israeli public discourse. As one of the first Haredi women to break into high-tech, and a pioneer of academia within the Haredi sector, she is leading a push to reform the Haredi education system. As director of the 'Haredim LaMedina' ('Haredim for the State') program and a founding member of the 'Believing Left' movement, she offers a distinctive voice linking a world of faith to left-wing values, social justice, and peace. Her political activity, including a run on the 'Ir Va'Em' list in Elad and in the Labor Party primaries, reflects her vision of integrating Haredi society into Israeli society while preserving its distinct identity. These days she's leading the surge in state-recognized Haredi education (mamlachti-haredi), a stream that has gained significant momentum in recent years." },
  "HPSKfs7juUQ": { title: "Knitted Kippah vs. Black Kippah, Episode 11, Akiva Novick", description: "Akiva Novick, anchor of the nightly news on Kan 11, opens up about the tension between the Israeli and the journalist in him during wartime. Raised in an ideological family from Ofra, he offers a nuanced view of the media, religious Zionism, and Haredi society." },
  "umzQBqRWcrc": { title: "What Happens When a Secular Lawyer Fights Haredi Women's Battles? Attorney Chagai Kalai", description: "Attorney Chagai Kalai is a key figure in Israel's legal and social arena, one of the leading players in the past decade's most burning legal battles for human rights and equality.\n\nThe man who stood before fifteen justices of the High Court of Justice (Bagatz), from the historic reasonableness-standard case to representing Haredi women in their fight against exclusion from public and political life, Kalai sits at the central fault lines of the tension between religion and state." },
  "n9TmOlzjzMI": { title: "Who's Afraid of Haredi Conscription? Episode 9, Rabbi Betzalel Cohen", description: "Rabbi Betzalel Cohen, an educator and Haredi social entrepreneur, joins the conversation about the space that allowed Chaim Walder, a beloved and revered Haredi author, to thrive. Rabbi Cohen wrote about the Chaim Walder affair on his blog: a beloved Haredi author who, according to numerous testimonies, sexually assaulted women, engaged in non-consensual sexual relations, had sexual relations with minors, and sexually abused children. The affair shook the Haredi world and surfaced a flood of testimony about sexual abuse and its mishandling. We talked about the spiritual dangers that worry young Haredim, the distance and alienation between Haredim and secular Israelis, the question of military service that the war has reignited, the fear that the State of Israel is turning into a 'halachic state,' and more." },
  "WjK5wo5xQY4": { title: "How Are Haredi Children Brought Into the World? Episode 8, Rachel Elitzur", description: "Rachel Elitzur, a Haredi director and screenwriter, creator of 'Wedding Night,' joins the conversation about sexuality and sexual relations in Haredi society, about the erasure of any discussion of what happens in the bedroom, about the moment when things you're forbidden even to think about suddenly become things you're expected to do, about the experience of rape that can occur on the wedding night, and more." },
  "DpLhi-VnKSU": { title: "\"What I Said to Netanyahu Came From My Heart's Blood\", Episode 7, Elchanan Danino", description: "Rabbi Elchanan Danino, father of Ori Danino, may his memory be a blessing, who was murdered in Hamas captivity together with Hersh Goldberg-Polin, Eden Yerushalmi, Almog Sarusi, Carmel Gat, and Alex Lobanov. Elchanan joins the conversation about Ori, about the grief he lives with, about Netanyahu's handling of deals that could have saved many hostages, the criticism he directs at the government, and more." },
  "XAvSq--TI8Q": { title: "Shas Forgot My Father's Path! Adina Bar-Shalom", description: "Adina Bar-Shalom, founder of the Haredi College in Jerusalem and recipient of the Israel Prize for lifetime achievement and special contribution to society and the state, speaks about Haredi public opinion, pikuach nefesh, the Jewish legal duty to save a life, and the obligation to bring the hostages home; about the need for unity and partnership between Haredim and secular Israelis; about her concern that Haredim remain part of the Jewish people; the country's future; and whether we are destined to live here forever by the sword." },
  "qd2Q6_bXt2Y": { title: "What Do Haredi Girls Know About Art? Hadassah Goldvicht on Making Art Out of Pain", description: "Hadassah Goldvicht, a multidisciplinary artist, author, and lecturer, explores in her work the relationship between language and ritual. In this episode, Goldvicht shares the personal journey that led her to make art about pain and healing, from car accidents to living with chronic pain.\n\nShe talks about an innovative project at the JCC in New York dealing with mechanisms of pain and healing, and about her exhibition 'Bibliyoscopia' at the Israel Museum. Goldvicht describes the challenges facing Haredi women artists and her role mentoring women artists in the Israeli art world. The conversation shows art's power to bridge worlds, heal pain, and give voice to those often left on the margins, in an ongoing dialogue across different communities and identities." },
  "KMZHIF2g1-I": { title: "What Is Haredi Feminism? Hila Hassan Lefkowitz, Chair of the Kfar Yona Religious Council", description: "Hila Hassan Lefkowitz, chair of the Kfar Yona Religious Council, shares her story on Haredit Meduberet as a Haredi woman holding a senior public office. She describes the challenges and successes of her role, including improving religious services for women and making them more accessible to the general public. Hila also talks about her run for the Knesset and her vision for women's representation in Haredi politics." },
  "grch6SyV-KI": { title: "From Racism to Art in Haredi Society, Eden Avitbul, Artist, Mizrahi, Second-Generation to Parents Who Returned to Observance", description: "Eden Avitbul, a poet, screenwriter, and weekly columnist for Makor Rishon (an Israeli newspaper), shares his personal and professional journey through Haredi culture.\n\nAs the son of baalei teshuva, parents who returned to religious observance, Avitbul describes the experience of feeling like a migrant and a stranger within Haredi society, and how it has shaped his art. Eden discusses the intersection of discrimination based on ethnic origin and being newly religious, and the difficulty of fitting into Haredi society while carrying a name as conspicuous, by Haredi standards, as 'Eden Avitbul.'" },
  "T9pE3FZh9aI": { title: "Who Represents Haredi Women in the Knesset? Esty Shushan Hosts Efrat Shukrun, Broadcaster and Social Activist", description: "In this fascinating episode of Haredit Meduberet, Esty Shushan talks with Efrat Shukrun, a broadcaster on Kan Moreshet and a social activist against the exclusion of Haredi women.\n\nEfrat, the daughter of former Knesset member Rabbi Chaim Amsalem, exposes the complicated reality Haredi women face in public life. She talks about her legal battle against the exclusion of women from public events and offers creative solutions for including women. Efrat shares her experience as a woman working in Haredi media and speaks about the importance of women's representation there. She also describes using social media as a tool for shifting attitudes within the Haredi community. Finally, Efrat talks about her singular path from a political household to becoming a presenter for the leadership program 'Nivcharot.' An in-depth conversation about gender equality, Haredi identity, and social change." },
  "27O4PfS5UgU": { title: "The Revolution in Haredi Society, Right Here, and Big Time! Eli Beitan, Journalist, Broadcaster, and Comedian", description: "Eli Beitan, journalist, broadcaster, and comedian, from cheder to Kan Moreshet, was born and raised in Ramat Beit Shemesh to a devout Haredi family.\n\nIn 2017, in his twenties, the state of the country left him pained and furious. He felt he had to act, and got up to speak at a left-wing rally in Rabin Square.\n\nIn the very first episode of Haredit Meduberet, Esty Shushan talks with Eli Beitan about Haredi activism and about his life as someone who left Haredi society." },
  "1000779519370": { title: "Dad Is Watching From Above and Always Loves Me", description: "Shas's election slogan was \"Dad is watching from above\"; \"God always loves me\" became the wartime anthem. A conversation with Ofir Tubul, culture and music researcher, jurist, and head of Beit Kulanu, about the fight for the traditional Mizrahi vote ahead of the elections." },
  "1000778389982": { title: "In My Community, No One Wants to Know What I Do", description: "Tzipi Horowitz, a Haredi woman who works in the Defense Ministry's rehabilitation division and accompanies wounded soldiers, on what it means to look, day after day, into the eyes of someone who risked everything, and to come home to a community that would rather not know." },
  "1000777411417": { title: "Game of Thrones in the Haredi Oligarchy", description: "From the \"Haredit Meduberet Votes\" series: commentator and journalist Eli Beitan on election trends on the Haredi street, the rift within Shas, the paralysis of Litvish leadership, and the Hasidim carving out independence from the state." },
  "1000776445006": { title: "A Women's Section in Academia", description: "On the bill that would extend gender-segregated study to advanced degrees too. Esty Shushan and Malka Rotner take back a debate that's always been held over the heads of Haredi women." },
  "1000775503560": { title: "Believers in Disagreement", description: "What separates Haredim from religious Zionism, and where the messianic ideas shaping both of them come from. A conversation with Rabbi Sefi Gladzahler, head of the \"HaRuach HaGedola\" study hall." },
  "1000774532131": { title: "A Route Around Beit Yaakov", description: "Yehudit Yifrach didn't study at Beit Yaakov, and she isn't a ba'alat teshuva either. A conversation about identity, culture, and love that wins out, about her life's journey within Haredi society, and the questions the war brought with it." },
}

export function translatedTitle(id: string, heTitle: string): Localized<string> {
  const translation = podcastTranslations[id]
  return { he: heTitle, en: translation?.title ?? heTitle }
}

export function translatedDescription(id: string, heDescription: string): Localized<string> {
  const translation = podcastTranslations[id]
  return { he: heDescription, en: translation?.description ?? heDescription }
}
